export type Continent =
  | 'Asia'
  | 'Europe'
  | 'North America'
  | 'South America'
  | 'Africa'
  | 'Oceania';

export type Hemisphere = 'Northern' | 'Southern';

export interface Country {
  name: string;
  capital: string;
  continent: Continent;
  iso: string;
  timezone: string;
  currency: string;
  currencySymbol: string;
  callingCode: string;
  population: number;
  language: string;
  lat: number;
  lng: number;
  hemisphere: Hemisphere;
}

